#include <limits>
template<typename T>
struct NumericLimits {
    static constexpr T infinity() noexcept { return T(); }
    static constexpr T quiet_NaN() noexcept { return T(); }
    static constexpr T signaling_NaN() noexcept { return T(); }
};
int main() {
    constexpr double inf = NumericLimits<double>::infinity();
    static_assert(inf == 0.0, "Infinity value for double is not zero in this simplified example");
    return 0;
}
